 inline(p,104);assert not row(p,103).locator('.group-inline-panel').count() and row(p,104).locator('.group-inline-panel').count()==1;assert not row(p,103).locator('[data-recipe-favorite]').count();row(p,104).locator('.master-category-meal-name').first.tap();assert p.locator('#recipeViewer').count()==1;button(p,'Close recipe').tap();assert row(p,104).locator('.group-inline-panel').count()==1
 row(p,104).get_by_role('button',name='Edit recipe',exact=True).tap();p.locator('#cancel').tap();assert row(p,104).locator('.group-inline-panel').count()==1
 row(p,104).get_by_role('button',name='Edit groceries',exact=True).tap();p.get_by_role('dialog',name='Edit groceries',exact=True).get_by_role('button',name='Cancel',exact=True).tap();assert row(p,104).locator('.group-inline-panel').count()==1
 row(p,104).get_by_role('button',name='Schedule meal',exact=True).tap();p.get_by_role('dialog',name='Schedule Meal',exact=True).get_by_role('button',name='Cancel',exact=True).tap();settle(p)
