 p.evaluate('follow121.home()');plan=p.locator('.plan-meal-card[data-schedule-day="Monday"]').first;plan.get_by_role('button',name='Meal actions for ',exact=False).first.tap();assert plan.locator('.plan-card-recipe [data-recipe-favorite]').count()==1 and not plan.locator('.expanded-meal-heading [data-recipe-favorite]').count();plan.locator('[data-recipe-favorite]').tap();assert plan.evaluate('(e)=>e.classList.contains("plan-card-expanded")');p.screenshot(path=str(OUT/(name+'-plan-heart.png')))
 assert not e,e;c.close();print('PASS',name,'inline singleton/name viewer, separate arrows, expanded name heart, favorite and editor/grocery/schedule returns, plan heart',flush=True)

