 before=raw(p);row(p,103).get_by_role('button',name='Edit groceries',exact=True).tap();d=p.get_by_role('dialog',name='Edit groceries',exact=True);d.get_by_role('textbox',name='New recipe ingredient',exact=True).fill('Discarded pepper');d.get_by_role('button',name='Add',exact=True).tap();back(p);prompt=p.get_by_role('dialog').last;prompt.get_by_role('button',name='No',exact=True).tap();settle(p);assert raw(p)==before and row(p,103).locator('.group-inline-panel').count()==1
