def renewed_planned_memberships(b,name):
 c,p,e,prefix=setup(b,name);p.evaluate('follow121.seedPlanned()');before=p.evaluate('follow121.plannedState()');schedule=p.evaluate('batch1.schedule()');organize(p,'Meals');select(p,1);d=menu(p);check_group(d,'Soup').check();apply_groups(p,d);assert p.evaluate('batch1.schedule()')==schedule and p.evaluate('follow121.plannedState()')==before
 source=next(m for m in raw(p)['meals'] if m['id']==1);copy=next(m for m in raw(p)['meals'] if m['cat']=='Soup' and m.get('linkGroup')==source.get('linkGroup'));organize(p);select(p,copy['id']);d=menu(p);check_group(d,'Soup').uncheck();apply_groups(p,d);assert p.evaluate('batch1.schedule()')==schedule and p.evaluate('follow121.plannedState()')==before;p.locator('#undo').tap();p.locator('#redo').tap();assert p.evaluate('follow121.plannedState()')==before;p.evaluate('group121.validate()');assert not e,e;c.close();print('PASS',name,'scheduled source copy/removal of extra membership preserves exact schedule, checked progress/scales/groceries and Undo/Redo',flush=True)

